/**
 * Catalog Alias & Semantic Retrieval Service
 * ==========================================
 * Manages the 3,156 canonical procedure alias mappings generated by the clinical audit.
 * Provides instant in-memory lookup for medical abbreviations, colloquial Egyptian Arabic names,
 * and clinical synonyms across all hospital departments.
 */

import { normalizeText, normalizeArabic, cleanHisProcedureQuery } from '../lib/arabic-normalizer';

export interface CatalogAliasEntry {
  alias_id: string;
  official_name: string;
  category: string;
  years_available: number[];
  aliases_en: string[];
  aliases_ar: string[];
  abbreviations: string[];
  catalog_occurrences: number;
}

let cachedEntries: CatalogAliasEntry[] | null = null;
let exactAliasMap: Map<string, string[]> | null = null;
let abbrevMap: Map<string, string[]> | null = null;
let loadPromise: Promise<CatalogAliasEntry[]> | null = null;

function buildIndexes(entries: CatalogAliasEntry[]): void {
  cachedEntries = entries;
  exactAliasMap = new Map<string, string[]>();
  abbrevMap = new Map<string, string[]>();

  for (const entry of entries) {
    const official = entry.official_name;

    // Index abbreviations
    for (const ab of entry.abbreviations) {
      const k = ab.toUpperCase().trim();
      if (!abbrevMap.has(k)) abbrevMap.set(k, []);
      const list = abbrevMap.get(k)!;
      if (!list.includes(official)) list.push(official);
    }

    // Index English aliases
    for (const a of entry.aliases_en) {
      const norm = normalizeText(a);
      if (norm) {
        if (!exactAliasMap.has(norm)) exactAliasMap.set(norm, []);
        const list = exactAliasMap.get(norm)!;
        if (!list.includes(official)) list.push(official);
      }
    }

    // Index Arabic aliases
    for (const a of entry.aliases_ar) {
      const norm = normalizeArabic(a);
      if (norm) {
        if (!exactAliasMap.has(norm)) exactAliasMap.set(norm, []);
        const list = exactAliasMap.get(norm)!;
        if (!list.includes(official)) list.push(official);
      }
    }
  }
}

/**
 * Loads the catalog aliases synchronously in Node (if available) or asynchronously in browser.
 */
export async function loadCatalogAliases(): Promise<CatalogAliasEntry[]> {
  if (cachedEntries) {
    return cachedEntries;
  }
  if (loadPromise) {
    return loadPromise;
  }

  loadPromise = (async () => {
    // 1. Node.js environment (server, tests, sync script)
    if (typeof window === 'undefined') {
      try {
        const fs = await import('fs');
        const path = await import('path');
        const filePath = path.resolve(process.cwd(), 'public', 'catalog_aliases.json');
        if (fs.existsSync(filePath)) {
          const raw = fs.readFileSync(filePath, 'utf-8');
          const data: CatalogAliasEntry[] = JSON.parse(raw);
          buildIndexes(data);
          return data;
        }
      } catch (err) {
        console.warn('[AliasService] Node load error for catalog_aliases.json:', err);
      }
    }

    // 2. Browser environment
    if (typeof window !== 'undefined') {
      try {
        const res = await fetch('/catalog_aliases.json');
        if (res.ok) {
          const data: CatalogAliasEntry[] = await res.json();
          buildIndexes(data);
          return data;
        }
      } catch (err) {
        console.warn('[AliasService] Browser fetch error for catalog_aliases.json:', err);
      }
    }

    return [];
  })();

  return loadPromise;
}

/**
 * Synchronous initialization for Node.js workflows.
 */
export function initCatalogAliasesSync(): void {
  if (cachedEntries || typeof window !== 'undefined') return;
  try {
    const fs = require('fs');
    const path = require('path');
    const filePath = path.resolve(process.cwd(), 'public', 'catalog_aliases.json');
    if (fs.existsSync(filePath)) {
      const raw = fs.readFileSync(filePath, 'utf-8');
      const data: CatalogAliasEntry[] = JSON.parse(raw);
      buildIndexes(data);
    }
  } catch {
    // Ignore fallback
  }
}

// Auto-init in Node if possible
if (typeof window === 'undefined') {
  try {
    initCatalogAliasesSync();
  } catch {
    // ignore
  }
}

/**
 * Resolves a search query (free-text, Arabic, or abbreviation) to candidate official catalog names.
 */
export function findOfficialNamesForQuery(query: string, arabicQuery?: string): string[] {
  if (!exactAliasMap || !abbrevMap) {
    // In Node, try sync init if not yet built
    initCatalogAliasesSync();
    if (!exactAliasMap || !abbrevMap) return [];
  }

  const results = new Set<string>();

  const cleanEng = cleanHisProcedureQuery(query);
  const qEngNorm = normalizeText(cleanEng);
  const qRawNorm = normalizeText(query);
  const qUpper = query.toUpperCase().trim();
  const qAraNorm = arabicQuery ? normalizeArabic(arabicQuery) : normalizeArabic(query);

  // 1. Check exact uppercase acronym (e.g. 'CBC', 'PTH', 'HRCT', 'KUB', 'MRCP')
  if (abbrevMap.has(qUpper)) {
    for (const name of abbrevMap.get(qUpper)!) {
      results.add(name);
    }
  }

  // 2. Check normalized English
  if (qEngNorm && exactAliasMap.has(qEngNorm)) {
    for (const name of exactAliasMap.get(qEngNorm)!) {
      results.add(name);
    }
  }
  if (qRawNorm && qRawNorm !== qEngNorm && exactAliasMap.has(qRawNorm)) {
    for (const name of exactAliasMap.get(qRawNorm)!) {
      results.add(name);
    }
  }

  // 3. Check normalized Arabic
  if (qAraNorm && exactAliasMap.has(qAraNorm)) {
    for (const name of exactAliasMap.get(qAraNorm)!) {
      results.add(name);
    }
  }

  // 4. Token-based fallback for multi-word queries
  if (results.size === 0 && cachedEntries) {
    const qTokens = (qEngNorm ? qEngNorm.split(/\s+/) : []).filter(t => t.length >= 3);
    const qAraTokens = (qAraNorm ? qAraNorm.split(/\s+/) : []).filter(t => t.length >= 3);

    if (qTokens.length >= 2 || qAraTokens.length >= 2) {
      for (const entry of cachedEntries) {
        let matched = false;
        if (qTokens.length >= 2) {
          for (const alias of entry.aliases_en) {
            const aTokens = new Set(normalizeText(alias).split(/\s+/));
            const overlap = qTokens.filter(t => aTokens.has(t)).length;
            if (overlap === qTokens.length) {
              results.add(entry.official_name);
              matched = true;
              break;
            }
          }
        }
        if (!matched && qAraTokens.length >= 2) {
          for (const alias of entry.aliases_ar) {
            const aTokens = new Set(normalizeArabic(alias).split(/\s+/));
            const overlap = qAraTokens.filter(t => aTokens.has(t)).length;
            if (overlap === qAraTokens.length) {
              results.add(entry.official_name);
              break;
            }
          }
        }
        if (results.size >= 10) break;
      }
    }
  }

  return Array.from(results);
}

/**
 * Returns all synonym strings for a query to feed into scoring and worker search.
 */
export function getAliasesForQuery(query: string, arabicQuery?: string): string[] {
  const officialNames = findOfficialNamesForQuery(query, arabicQuery);
  if (officialNames.length === 0 || !cachedEntries) return [];

  const synonyms = new Set<string>();
  const officialSet = new Set(officialNames);

  for (const entry of cachedEntries) {
    if (officialSet.has(entry.official_name)) {
      synonyms.add(entry.official_name);
      for (const a of entry.aliases_en) synonyms.add(a);
      for (const a of entry.aliases_ar) synonyms.add(a);
      for (const ab of entry.abbreviations) synonyms.add(ab);
    }
  }

  return Array.from(synonyms);
}
